package render

import "fmt"

type Input struct {
	Tokens int
	Cached int
}

func Footnote(in Input) string {
	if in.Tokens == 0 {
		return ""
	}
	return tokenLine(in.Tokens, in.Cached)
}

func tokenLine(total, cached int) string {
	return fmt.Sprintf("%d tokens (%d cached)", total, cached)
}
